-- Rollback-only synthetic customers. No Horizonte state is entered or changed.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('4d8e0000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,email_confirmed_at,encrypted_password) values(pg_temp.id(1),'authenticated','authenticated','staff-admin-sql@example.invalid',clock_timestamp(),'synthetic');
insert into persons(id,auth_user_id,display_name) values(pg_temp.id(2),pg_temp.id(1),'Fictional Delegator');
insert into accounts(id,code,name,tenant_kind) values(pg_temp.id(3),'STAFF-SQL-C','Fictional Customer','customer'),(pg_temp.id(13),'STAFF-SQL-S','Fictional Sandbox','sandbox');
insert into schools(id,account_id,code,name) values(pg_temp.id(4),pg_temp.id(3),'S','Fictional School'),(pg_temp.id(14),pg_temp.id(13),'S','Fictional Sandbox School');
insert into school_locations(id,account_id,school_id,code,name) values(pg_temp.id(5),pg_temp.id(3),pg_temp.id(4),'L','Fictional Location'),(pg_temp.id(15),pg_temp.id(13),pg_temp.id(14),'L','Fictional Sandbox Location');
insert into cafeterias(id,account_id,school_id,school_location_id,code,name) values(pg_temp.id(6),pg_temp.id(3),pg_temp.id(4),pg_temp.id(5),'C','Fictional Cafe'),(pg_temp.id(16),pg_temp.id(13),pg_temp.id(14),pg_temp.id(15),'C','Fictional Sandbox Cafe');
insert into account_memberships(account_id,person_id,role_code) values(pg_temp.id(3),pg_temp.id(2),'account_admin');
insert into auth.sessions(id,user_id,created_at,updated_at) values(pg_temp.id(7),pg_temp.id(1),clock_timestamp(),clock_timestamp());
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(1),'role','authenticated','session_id',pg_temp.id(7))::text,true);
insert into cafeteria_memberships(account_id,school_id,cafeteria_id,person_id,role_code) values(pg_temp.id(3),pg_temp.id(4),pg_temp.id(6),pg_temp.id(2),'cafeteria_admin');
create temp table saved(k text primary key,v jsonb);grant all on saved to authenticated;
create function pg_temp.s(k text) returns text language sql as $$select v#>>'{}' from saved where saved.k=$1$$;
set local role authenticated;
select pikas_session_start();
insert into saved values('invitation',to_jsonb(cafeteria_admin_command(pg_temp.id(6),pg_temp.id(8),'staff_prepare',jsonb_build_object('email','staff-new-sql@example.invalid','role','pos_cashier'))->>'target_id'));
select is(cafeteria_staff_activation_status(pg_temp.s('invitation')::uuid)->>'identity_state','missing','same existing pending invitation lacks identity');
insert into saved values('reservation',cafeteria_prepare_staff_activation(pg_temp.s('invitation')::uuid));
insert into saved values('handle',to_jsonb((select v->>'handle' from saved where k='reservation')));
reset role;
insert into auth.users(id,aud,role,email,encrypted_password,raw_app_meta_data) select pg_temp.id(30),'authenticated','authenticated',email_key,'baseline',jsonb_build_object('pikas_activation_owner',owner_key) from pikas_private.account_activation_flows where source_kind='cafeteria_staff' and source_handle=pg_temp.s('invitation');
set local role authenticated;
select lives_ok($$select cafeteria_bind_staff_activation(pg_temp.s('invitation')::uuid,pg_temp.s('handle'),encode(extensions.digest(pg_temp.s('handle'),'sha256'),'hex'))$$,'bind source-owned identity');
select lives_ok($$select cafeteria_bind_staff_activation(pg_temp.s('invitation')::uuid,pg_temp.s('handle'),encode(extensions.digest(pg_temp.s('handle'),'sha256'),'hex'))$$,'exact bind retry');
select throws_ok($$select cafeteria_bind_staff_activation(pg_temp.s('invitation')::uuid,pg_temp.s('handle'),encode(extensions.digest('changed-'||pg_temp.s('handle'),'sha256'),'hex'))$$,'42501','invitation_unavailable','changed digest rejected');
reset role;
update auth.users set email_confirmed_at=clock_timestamp() where id=pg_temp.id(30);
set local role authenticated;
select throws_ok($$select cafeteria_admin_command(pg_temp.id(6),pg_temp.id(9),'staff_complete',jsonb_build_object('invitation_id',pg_temp.s('invitation'),'display_name','Fictional Cashier'))$$,'23514','confirmed_identity_pending','email confirmation alone cannot grant POS');
reset role;
select is((select count(*)::int from persons where auth_user_id=pg_temp.id(30)),0,'activation grants zero Person');
select is((select count(*)::int from pikas_private.cafeteria_admin_requests where request_id=pg_temp.id(9)),0,'denied completion has no journal');
update auth.users set encrypted_password='synthetic-first-password' where id=pg_temp.id(30);
set local role authenticated;
select is(cafeteria_staff_activation_status(pg_temp.s('invitation')::uuid)->>'identity_state','ready','actual hash change recovers lost finalize');
select lives_ok($$select cafeteria_admin_command(pg_temp.id(6),pg_temp.id(9),'staff_complete',jsonb_build_object('invitation_id',pg_temp.s('invitation'),'display_name','Fictional Cashier'))$$,'explicit completion succeeds');
select lives_ok($$select cafeteria_admin_command(pg_temp.id(6),pg_temp.id(9),'staff_complete',jsonb_build_object('invitation_id',pg_temp.s('invitation'),'display_name','Fictional Cashier'))$$,'lost successful completion exact retry');
select throws_ok($$select cafeteria_admin_command(pg_temp.id(6),pg_temp.id(9),'staff_complete',jsonb_build_object('invitation_id',pg_temp.s('invitation'),'display_name','Changed'))$$,'23505','request_key_reused','changed request fails closed');
reset role;
select is((select count(*)::int from cafeteria_memberships m join persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(30) and m.cafeteria_id=pg_temp.id(6) and m.role_code='pos_cashier'),1,'exact cashier membership once');
select is((select count(*)::int from cafeteria_memberships m join persons p on p.id=m.person_id where p.auth_user_id=pg_temp.id(30) and m.role_code='cafeteria_admin'),0,'no administration role');
select is((select count(*)::int from cafeteria_register_assignments where cafeteria_id=pg_temp.id(6)),0,'no register assignment');
select is((select count(*)::int from audit_events where request_id=pg_temp.id(9) and actor_person_id=pg_temp.id(2) and authenticated_user_id=pg_temp.id(1)),1,'real actor audit once');
select ok(not has_function_privilege('anon','public.cafeteria_prepare_staff_activation(uuid)','execute'),'anon cannot issue');
select ok(not has_function_privilege('service_role','public.cafeteria_prepare_staff_activation(uuid)','execute'),'provider cannot issue');
insert into persons(id,display_name) values(pg_temp.id(17),'Fictional Authless Persona');
insert into cafeteria_memberships(id,account_id,school_id,cafeteria_id,person_id,role_code) values(pg_temp.id(18),pg_temp.id(13),pg_temp.id(14),pg_temp.id(16),pg_temp.id(17),'cafeteria_admin');
insert into pikas_private.sandbox_pov_personas(id,account_id,school_id,cafeteria_id,pov_code,person_id,cafeteria_membership_id) values(pg_temp.id(19),pg_temp.id(13),pg_temp.id(14),pg_temp.id(16),'cafeteria_admin',pg_temp.id(17),pg_temp.id(18));
insert into pikas_private.sandbox_pov_sessions(request_id,initiator_person_id,initiator_auth_user_id,account_id,school_id,cafeteria_id,pov_code,persona_id,persona_person_id,persona_membership_id,expires_at) values(pg_temp.id(20),pg_temp.id(2),pg_temp.id(1),pg_temp.id(13),pg_temp.id(14),pg_temp.id(16),'cafeteria_admin',pg_temp.id(19),pg_temp.id(17),pg_temp.id(18),clock_timestamp()+interval '1 hour');
set local role authenticated;
select throws_ok($$select cafeteria_prepare_staff_activation(pg_temp.s('invitation')::uuid)$$,'42501','real_cafeteria_admin_required','sandbox POV cannot issue');
select * from finish();
rollback;
